"""Regenerate the static prototype with Python 3 (no dependencies required)."""
from pathlib import Path
from html import escape as esc
import json
ROOT=Path(__file__).resolve().parent
EMAIL='mailto:nationalboard@bostonpublicschools.org'
FORM='https://docs.google.com/forms/d/e/1FAIpQLSf24khnzlIkLbEDB9HJsMRWrO93wDDtg4Ml_Pz-cNfGU7yzzw/viewform'
NAV=[('certification','Certification'),('support','Candidate support'),('resources','Resources'),('community','Our community'),('teaching','Teaching practice')]
def link(url,text,cls=''):
 return f'<a href="{esc(url,quote=True)}"'+(f' class="{cls}"' if cls else '')+f'>{text}</a>'
def button(url,text,style=''): return link(url,text,'button '+style)
def icon(kind='book'):
 shapes={'book':'<path d="M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3zM12 6v15"/>','people':'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 4v3"/>','leaf':'<path d="M5 20C3 8 9 3 21 3c0 12-5 18-16 17ZM5 20 16 9"/>'}
 return f'<span class="icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">{shapes.get(kind,shapes["book"])}</svg></span>'
def card(title,desc,url,label,tag='',kind=None):
 return f'<article class="card">{icon(kind) if kind else ""}{f"<span class=tag>{tag}</span>" if tag else ""}<h3>{title}</h3><p>{desc}</p>{link(url,label)}</article>'
def cta(): return f'<section class="section"><div class="wrap"><div class="callout"><div><h2>You don’t have to do this alone.</h2><p>Connect with the National Board Leadership Team to find the right next step for you.</p></div>{button("contact.html","Connect with our team","gold")}</div></div></section>'
def brand(): return '<a class="brand" href="index.html"><span><strong>Boston<br>National Board</strong><small>BPS / BTU</small></span></a>'

def shell(slug,title,body,active=None):
 nav=''.join(f'<a href="{s}.html"'+(' aria-current="page"' if (active or slug)==s else '')+f'>{t}</a>' for s,t in NAV)
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)} | BPS/BTU National Board Program</title><meta name="description" content="National Board certification resources, candidate support, and professional community for Boston educators."><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="styles.css"><script src="app.js" defer></script></head><body><a class="skip" href="#main">Skip to main content</a><div class="utility"><div class="wrap"><span>A partnership for accomplished teaching in Boston</span><span>{link('contact.html','Contact the team')} &nbsp; / &nbsp; Design prototype</span></div></div><header><div class="wrap header-inner">{brand()}<button class="menu" aria-expanded="false" aria-controls="primary-nav">Menu</button><nav id="primary-nav" aria-label="Main navigation">{nav}<a class="nav-cta" href="contact.html">Get updates</a></nav></div></header><main id="main">{body}</main><footer><div class="wrap"><div class="foot-grid"><div>{brand()}<p>Elevating teaching. Empowering teachers.<br>A professional learning community for Boston educators.</p>{link(EMAIL,'nationalboard@bostonpublicschools.org','contact-email')}</div><div><h3>Find your next step</h3><ul><li>{link('certification.html','Explore certification')}</li><li>{link('support.html','Find candidate support')}</li><li>{link('moc.html','Maintain your certification')}</li><li>{link('resources.html','Browse all resources')}</li></ul></div><div><h3>Stay connected</h3><ul><li>{link('community.html','Boston NBCT community')}</li><li>{link('events.html','Events & writing retreats')}</li><li>{link('opportunities.html','Leadership opportunities')}</li><li>{link('contact.html','Contact us')}</li></ul></div></div><div class="foot-bottom"><span>BPS / BTU National Board Program</span><span>Editorial prototype · November 2026 &nbsp; {link('https://sites.google.com/bostonpublicschools.org/nblt/home','Original Google Site')}</span></div></div></footer></body></html>'''
 (ROOT/(slug+'.html')).write_text(html)
def head(title,intro,kicker='Boston National Board Program'):
 return f'<section class="page-head"><div class="wrap"><div class="crumb">{link("index.html","Home")}<span>/</span><span>{title}</span></div><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="intro">{intro}</p></div></section>'
def page(slug,title,intro,content,active=None,wide=False):
 aside='<aside class="aside"><h2>In this program</h2>'+''.join(link(s+'.html',t) for s,t in NAV)+link('events.html','Events & writing retreats')+link('contact.html','Contact the team')+'</aside>'
 body=head(title,intro)+f'<section class="section"><div class="wrap'+('' if wide else ' layout')+'"><div class="'+('' if wide else 'content')+'">'+content+'</div>'+('' if wide else aside)+'</div></section>'+cta()
 shell(slug,title,body,active)
home = '<section class="editorial-hero"><div class="hero-orbit orbit-blue" aria-hidden="true"></div><div class="hero-orbit orbit-coral" aria-hidden="true"></div><div class="hero-orbit orbit-gold" aria-hidden="true"></div><div class="wrap editorial-grid"><div class="hero-copy"><p class="eyebrow">Boston educators. Greater possibilities.</p><h1>Great teaching.<br><em>Greater<br>possibilities.</em></h1><p>Your next chapter in accomplished teaching starts here.</p><div class="actions">'+button('certification.html','Explore certification','gold')+button('support.html','Find your support','outline')+'</div></div><div class="hero-visual"><span class="sunburst" aria-hidden="true">'+''.join(f'<i style="--i:{i}"></i>' for i in range(18))+'</span><div class="arch-photo"><img src="assets/educators.jpg" alt="Boston educators sharing feedback and developing their National Board portfolios at a program writing retreat" width="1280" height="767"></div><span class="photo-label">Our educators. Our community.</span></div></div></section><section class="journey-section"><div class="wrap"><div class="editorial-heading"><h2>Where are you in your journey?</h2><span aria-hidden="true"></span></div><div class="journey-grid"><a class="journey-card coral" href="certification.html"><h3>Getting<br>started</h3><p>Curious about National Board Certification? Learn what it is, who it’s for, and how it can deepen your practice and impact.</p><span class="card-action">Explore certification</span></a><a class="journey-card cobalt" href="support.html"><h3>Working toward<br>certification</h3><p>Already on the path? Find guidance, resources, and collegial support to keep your work focused, manageable, and meaningful.</p><span class="card-action">Find your support</span></a><a class="journey-card plum" href="community.html"><h3>Already<br>certified</h3><p>Continue to grow, lead, and make an impact. Stay connected, support colleagues, and extend your influence in Boston.</p><span class="card-action">Connect with colleagues</span></a></div><div class="story-grid"><a class="story-card" href="events.html"><div class="story-photo photo-learning" role="img" aria-label="Boston educators working together at a National Board writing retreat"></div><div class="story-copy"><h3>Learn together</h3><p>Build your practice alongside colleagues through collaboration, study, and shared expertise.</p><span class="card-action">Explore writing retreats</span></div></a><a class="story-card" href="community.html"><div class="story-photo photo-community" role="img" aria-label="Colleagues discussing their work during a Boston National Board writing retreat"></div><div class="story-copy"><h3>Meet the community</h3><p>Connect with Boston educators who are pursuing, achieving, and living the work of accomplished teaching.</p><span class="card-action">Meet the Boston network</span></div></a></div></div></section><section class="editorial-connect"><div class="wrap connect-grid"><div><p class="eyebrow">Keep the conversation going</p><h2>Stay connected to<br>what’s next.</h2><p>Ask about program updates, support opportunities, and ways to get involved in our community.</p>'+button(EMAIL+'?subject=National%20Board%20program%20updates','Get program updates','gold')+'</div><div class="connect-photo"><img src="assets/retreat-room.jpg" alt="Boston educators gathered for focused writing and collaboration at a program retreat" width="1280" height="960" loading="lazy"><span>Space to reflect. People to grow with.</span></div></div></section><div class="quickbar"><div class="wrap"><span>Keep these close</span>'+link('readers.html','Request a reader')+link('courses.html','Component courses')+link('resources.html','Resource library')+link('moc.html','Maintain certification')+'</div></div>'

shell('index','Home',home)
page('certification','Your path to National Board Certification','A meaningful next step in your professional growth, supported by a community of Boston educators.', '''<h2>Build on the teaching you do every day.</h2><p>National Board Certification is a voluntary process through which teachers demonstrate accomplished practice against national standards. It brings together reflection, classroom evidence, and a focus on student learning.</p><p>You don’t have to have every answer before you begin. Start by learning about the process, exploring your certificate area, and talking with the Boston team.</p><h2>Start here</h2><div class="grid two">'''+card('Learn about the process','Explore National Board’s introductory resources and find your starting point.','https://www.nbpts.org/homeroom/','Visit NBPTS Homeroom')+card('Talk with the Boston team','Bring questions about the commitment, cost, and local support options.','info-sessions.html','Explore information sessions')+'''</div><h2>Connect your learning to your classroom</h2><p>The process draws on what you know, how you respond to students, and how you reflect on your instruction. Boston’s support options include component courses, cohorts, trained readers, and writing retreats.</p>'''+button('support.html','Explore candidate support')+'''<h2>Benefits and professional growth</h2><p>Certification can support professional recognition, leadership, and ongoing learning. For current information about salary differentials, fee reimbursement, licensure, and graduate credits, use the benefits resources and confirm requirements with the appropriate office.</p>'''+link('benefits.html','Explore benefits & reimbursement'))
page('support','Support for every step','Find the structure, feedback, and community that help you move through the certification process.', '<div class="grid two">'+card('Component courses','Explore Components 2 and 3 through collaborative professional learning and classroom reflection.','courses.html','Explore component courses',kind='book')+card('Candidate cohorts','Work alongside other candidates with guidance from a trained facilitator.','cohorts.html','Learn about cohorts',kind='people')+card('NBCT readers','Receive feedback on draft components from trained National Board Certified Teachers.','readers.html','Learn how to request a reader',kind='book')+card('Writing retreats','Set aside focused time to write, reflect, and connect with experienced educators.','events.html','Explore writing retreats',kind='leaf')+card('Maintenance of Certification','Find resources and support for your next chapter as an NBCT.','moc.html','Explore MOC support',kind='leaf')+card('Tools & resources','Find component materials, session recordings, planning tools, and learning platforms.','resources.html','Browse the resource library',kind='book')+'</div><div class="actions">'+button(FORM,'Request information about support')+'</div>',wide=True)
page('cohorts','Candidate cohorts','Build momentum with a small community of educators working toward National Board Certification.', '''<h2>A structure for shared progress</h2><p>Cohort facilitators help candidates navigate portfolio instructions, understand the process, connect with resources, and build accountability partnerships.</p><p>Cohort support complements the feedback provided by an assigned NBCT reader. Ask the team about current cohort availability, meeting formats, and the best fit for your certificate area.</p><h2>Find your cohort</h2><p>Use the program’s interest form to share what you’re working on and learn about support options.</p>'''+button(FORM,'Ask about cohort support'),active='support')
page('courses','Component courses','Reflect on your classroom practice through collaborative learning focused on Components 2 and 3.', '''<div class="notice"><strong>Registration update</strong><p>The source site lists 2025–26 course registration as closed. Contact the team for the next offering; the documents below describe the previous cycle.</p></div><h2>Learn through your own teaching</h2><p>Use student work, instructional materials, and classroom video to examine your practice with peers. These courses connect professional learning with work toward a National Board component.</p><div class="grid two">'''+card('Component 2','Differentiation in Instruction: examine student work and how you respond to individual learning needs.','https://docs.google.com/document/d/11zwaHhqMm2KrYzKJztvqT-xzwZGkevP1YEEsnXnG7uQ/edit','Read the Component 2 course overview')+card('Component 3','Examining Teaching Practice & the Learning Environment: use classroom evidence to reflect on instruction.','https://docs.google.com/document/d/13lvXAQ9zk35__AZ8-rB6P3cZ1cYrDJ37oTGH5L23HUM/edit','Read the Component 3 course overview')+'''</div><h2>What to expect</h2><ul><li>Facilitated learning with National Board Certified Teachers.</li><li>Peer feedback on classroom evidence and written reflection.</li><li>Independent time to select artifacts and develop commentary.</li><li>A focus on instructional practice and student learning.</li></ul><p>Confirm dates, eligibility, registration fees, and credit availability with the program before enrolling.</p>'''+link('https://docs.google.com/document/d/1KufdDbMwPTe6GUhKobawPCjgDv-0HAMn_RFjZEYUAAA/edit','View the 2025–26 schedules & facilitator teams'),active='support')
page('readers','Feedback from NBCT readers','Get a thoughtful second look at your component drafts before submission.', '''<h2>How to request a reader</h2><div class="grid two">'''+card('If you’re in a cohort','Email your cohort leader to request a reader assignment. Your leader coordinates the match.','cohorts.html','About cohort support')+card('If you’re outside a cohort or pursuing MOC','Email the reader coordinator with your name, certificate area, and the component(s) you’re working on.','mailto:kfrazierbooth@bostonpublicschools.org','Email the reader coordinator')+'''</div><h2>What readers provide</h2><ul><li>Up to two reads per component.</li><li>Feedback through questions that support reflection on your practice.</li><li>Attention to component requirements and the clarity of your writing.</li></ul><p>Readers focus on your response to the prompts and evidence of practice. They do not provide spelling and grammar editing.</p><h2>Plan ahead</h2><p>Request a match well before the submission deadline. The program asks candidates to provide a draft at least two weeks before the deadline to allow time for feedback.</p><p>All reader assignments are coordinated through a cohort leader or the National Board Leadership Team.</p>''',active='support')
page('moc','Maintenance of Certification','Keep growing as an accomplished teacher and connect with support for maintaining your certification.', '''<h2>Reflect on your professional growth</h2><p>Maintenance of Certification (MOC) centers on professional growth experiences and their impact on student learning. Use the official National Board guidance for current requirements and timelines.</p><div class="actions">'''+button('https://www.nbpts.org/certification/candidate-center/maintaining-your-certification/moc-guide/','Read the official MOC guide')+button(FORM,'Ask about MOC support','light')+'''</div><h2>Find support in Boston</h2><ul><li>Ask about a cohort to work alongside other MOC candidates.</li><li>Request an assigned reader for feedback on your component drafts.</li><li>Connect with the Boston NBCT community to learn from colleagues.</li></ul><h2>Planning resources</h2><p>Find the MOC brainstorming document, official FAQs, archived webinars, and the self-guided Canvas course in the resource library.</p>'''+link('resources.html','Browse MOC resources'),active='support')
page('events','Events & writing retreats','Make time for reflection, focused writing, and connection with other Boston educators.', '''<h2>2027 writing retreats</h2><div class="notice"><strong>Dates to be announced</strong><p>The source site states that dates for the 2027 writing cycle have not been set and will be published pending funding.</p></div><p>Writing retreats offer a quiet space to work, an opportunity to connect with a reader, and support from experienced cohort leaders.</p>'''+button(EMAIL+'?subject=Writing%20retreat%20updates','Ask about upcoming retreats')+'''<h2>Information sessions</h2><p>Explore the certification process and bring your questions about time, cost, and local support.</p>'''+link('info-sessions.html','Learn about information sessions')+'''<h2>NBCT network events</h2><p>Connect with the leadership team for current opportunities to meet other certified teachers in Boston.</p>'''+link('community.html','Connect with the NBCT community')+'''<h2>Past events</h2><details><summary>2026 writing retreat schedule</summary><p>March 21 and March 28, 9 a.m.–noon at Emmanuel College; May 9, 9 a.m.–noon at the BTU Union Hall, 180 Mt. Vernon St., Dorchester. These dates are archived.</p></details><details><summary>2025 educator appreciation event</summary><p>The original ticket purchase deadline was June 20, 2025. This event is retained in the resource archive for reference.</p></details>''',active='community')
page('info-sessions','Information sessions','A welcoming place to ask questions and explore whether National Board Certification is right for you.', '''<h2>Bring your questions</h2><p>Connect with the Boston National Board Leadership Team to discuss the process and the support available to you.</p><ul><li>How does the work fit into a school year?</li><li>What does certification cost?</li><li>What kinds of support are available?</li><li>How can the process strengthen my classroom practice?</li><li>What should I do first?</li></ul><p>Contact the team for current session dates and joining details.</p>'''+button(EMAIL+'?subject=National%20Board%20information%20sessions','Ask about an information session'),active='certification')
page('community','A community of accomplished teachers','Connect with Boston NBCTs, share your expertise, and continue growing together.', '''<div class="grid two">'''+card('Boston NBCT network','Are you a National Board Certified Teacher working in Boston? Contact the team to join the NBCT listserv.','contact.html','Connect with the network',kind='people')+card('National NBCT directory','Find educators who have earned National Board Certification using the official directory.','https://www.nbpts.org/nbct-directory/','Visit the NBCT directory',kind='book')+card('Events & connections','Meet colleagues and stay connected through the Boston network.','events.html','Explore events & updates',kind='people')+card('Share your expertise','Explore faculty and leadership roles that support candidates and strengthen teaching.','opportunities.html','Explore leadership opportunities',kind='leaf')+'''</div><div class="actions">'''+button('moc.html','Explore Maintenance of Certification')+'</div>',wide=True)
page('opportunities','Share your expertise','Support fellow educators through reading, facilitation, and program leadership.', '''<div class="notice"><strong>Check current availability with the team</strong><p>Several recruitment notices in the source site reference 2024–25. They are presented here as role information, not active vacancies.</p></div><h2>Candidate support faculty</h2><details open><summary>On-call readers</summary><p>Support candidates by reading draft components and offering reflective feedback. Readers participate in training, follow the program’s feedback protocol and ethical support guidelines, and keep an activity log.</p></details><details><summary>Cohort facilitators</summary><p>Guide groups of candidates through portfolio instructions and the certification process, build accountability, and connect educators with useful resources.</p></details><details><summary>Component course leaders</summary><p>Facilitate collaborative professional learning around classroom evidence, teaching practice, and component development.</p></details><p style="margin-top:24px">Ask the leadership team about current openings, application status, compensation, and training before applying.</p>'''+button(EMAIL+'?subject=Candidate%20support%20faculty%20opportunities','Ask about faculty opportunities')+'''<h2>National Board Leadership Team</h2><p>Learn about the program leadership role and contact the team about current recruitment. The May 2025 application deadline shown on the original page has passed.</p>'''+link('https://docs.google.com/document/d/1AOY-apH1ggKZYz50boUCo3kATM1AqWH_8RjtRTRRgIc/edit','Read the leadership team job description')+'''<h2>Margins to Center · project archive</h2><p>The Margins to Center project supported work to strengthen candidate support and increase participation by teachers of color. The source’s lead-role terms ended in October 2025, and applications were closed.</p><p>Project background and role references are preserved in the resource library under “Archives.”</p>'''+link('resources.html','Browse the resource library'),active='community')
page('benefits','Benefits & reimbursement','Find the right starting point for questions about recognition, reimbursement, and professional learning credit.', '''<div class="notice"><strong>Confirm current requirements</strong><p>The original website includes older pay, reimbursement, and credit guidance. Confirm current terms and procedures with BPS, BTU, and the relevant provider before making a financial or professional decision.</p></div><h2>Certification fee reimbursement</h2><p>Keep your National Board registration and assessment receipts. Ask the leadership team for the current reimbursement contact, documentation requirements, and submission process.</p>'''+link(EMAIL+'?subject=Certification%20fee%20reimbursement','Ask about fee reimbursement')+'''<h2>Salary differential</h2><p>The source site describes a 4% salary differential and submission of certification documentation with a PS03 form. Ask Employee Services to confirm the current contract terms, required form, and effective date.</p>'''+link('mailto:EmployeeServices@bostonpublicschools.org','Contact BPS Employee Services')+'''<h2>Graduate credit</h2><p>Explore George Mason University’s National Board credit options and confirm availability, cost, and eligibility directly with the provider.</p>'''+link('https://education.gmu.edu/teacher-professional-development/nbpts-options-at-mason/nbct-achievement','Explore George Mason credit options'),active='resources')
page('teaching','Advancing accomplished teaching','Bring the principles of National Board Certification into your classroom, school, and professional learning community.', '''<div class="grid two">'''+card('Five Core Propositions','Explore what teachers should know and be able to do, and use the propositions to guide reflection.','https://www.nbpts.org/certification/five-core-propositions/','Read the Five Core Propositions')+card('Standards for accomplished teaching','Explore accomplished practice within specific subject areas and developmental levels.','https://www.nbpts.org/certification/standards/#standards','Explore the standards')+card('ATLAS video cases','Study authentic classroom cases and discuss teaching practice with colleagues.','https://www.nbpts.org/support/atlas/','Explore ATLAS')+card('Tools for schools & leaders','Find conversation frameworks, reflection questions, study bundles, and leadership toolkits.','resources.html','Browse teaching practice resources')+'''</div><h2 style="margin-top:48px">Architecture of Accomplished Teaching</h2><p>A framework for connecting what you know about your students with goals, instruction, assessment, and reflection.</p><a href="assets/architecture-of-accomplished-teaching.jpg"><img class="diagram" src="assets/architecture-of-accomplished-teaching.jpg" loading="lazy" alt="Architecture of Accomplished Teaching: know students, set learning goals, implement instruction, evaluate learning, reflect, and set new goals." width="1650" height="1275"></a><p>'''+link('assets/architecture-of-accomplished-teaching.jpg','Open the full-size teaching framework')+'''</p><div class="notice">ATLAS cases can support reflection on teaching, but the original site notes that cases may reflect pre-2014 certification requirements. Use current National Board instructions for your submission.</div>''',wide=True)
page('contact','Let’s find your next step.','Reach out to the National Board Leadership Team for help with certification, candidate support, or the Boston NBCT network.', '''<h2>Contact the program</h2><p>Send your question to the shared program inbox, and a member of the team will respond.</p>'''+link(EMAIL,'nationalboard@bostonpublicschools.org','big-link contact-email')+'''<h2>Interested in candidate support?</h2><p>Use the program’s interest form to share the support you’re looking for.</p>'''+button(FORM,'Complete the support interest form')+'''<h2>Looking for a reader?</h2><p>If you’re in a cohort, contact your cohort leader. If you’re outside a cohort or pursuing MOC, follow the reader request instructions.</p>'''+link('readers.html','View reader request instructions'))
resources=json.loads((ROOT/'resources.json').read_text())
filters=['All resources','Certification','Components','MOC','Teaching practice','Archives']
body='<div class="search-box"><label for="resource-search">Find a resource</label><input id="resource-search" type="search" placeholder="Search by title, topic, or source…"></div><div class="filters" aria-label="Filter resources by topic">'+''.join(f'<button type="button" aria-pressed="{str(i==0).lower()}">{t}</button>' for i,t in enumerate(filters))+'</div><p id="result-count" class="count" role="status" aria-live="polite"></p><noscript><p>All resources are listed below. Enable JavaScript to search and filter.</p></noscript><div id="resource-list">'
for r in resources:
 body+=f'<article class="resource" data-category="{esc(r["category"])}"><div><h3>{link(r["url"],esc(r["title"]))}</h3><p>{esc(r["source"])} · {esc(r["category"])}</p></div><span class="tag">{esc(r["type"])}</span></article>'
body+='</div><p id="empty" class="empty" hidden>No resources match your search. Try another term or choose “All resources.”</p><div class="notice" style="margin-top:35px">Google Drive, Canvas, and other external resources may require access or sign-in. Archived materials retain their original dates; confirm current requirements with the program.</div>'
page('resources','The resource library','One organized home for the guides, tools, and learning materials that support your journey.',body,wide=True)
print('Generated',len(list(ROOT.glob('*.html'))),'pages')
